#include <cstdio>
#include <algorithm>

using namespace std;

long long d[10], v[10];

long long gcd(long long a, long long b) {
    while (b) {
        long long temp = b;
        b = a % b; 
        a = temp;
    }
    return a;
}

void compute(int n) {
    long long common_gcd = gcd(d[n], v[n]);
    d[n] /= common_gcd;
    v[n] /= common_gcd;
}

int main() {
    int n;
    while (scanf("%d", &n), n) {
        long long a, b;
        for (int i = 0; i < n; i++) {
            scanf("%lld %lld", &d[i], &v[i]);
            compute(i);
        }
        a = d[0];
        b = v[0];
        for (int i = 1; i < n; i++) {
            a = (a * d[i]) / gcd(a, d[i]);
            b = gcd(b, v[i]);
        }
        for (int i = 0; i < n; i++) {
            printf("%lld\n", a * v[i] / (b * d[i]));
        }
    }
    return 0;
}

